export function retryPromise<T>(make: () => Promise<T>, max: number): Promise<T> {
  let attempt = 0;
  const run = (): Promise<T> =>
    make().catch((e) => {
      attempt += 1;
      return attempt < max ? run() : Promise.reject(e);
    });
  return run();
}

