export function cartTotal(lines: { price: number; qty: number; vat: number }[]): number {
  let total = 0;
  for (const line of lines) {
    const net = line.price * line.qty;
    total += net + net * line.vat;
  }
  return Math.round(total * 100) / 100;
}

