export function distinctEntities<E extends { id: string }>(list: E[]): E[] {
  const byId: Record<string, E> = {};
  const order: string[] = [];
  for (const e of list) {
    if (!(e.id in byId)) {
      byId[e.id] = e;
      order.push(e.id);
    }
  }
  return order.map((id) => byId[id]);
}

